import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.CDU0sSpB.js";const h=JSON.parse('{"title":"4.1 Set triggers and proactive suggestions","description":"Find work worth doing and explain why it matters now.","frontmatter":{"title":"4.1 Set triggers and proactive suggestions","description":"Find work worth doing and explain why it matters now.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/stage-4/4-1.md","filePath":"en/delivery/stage-4/4-1.md","lastUpdated":1794015952000}'),o={name:"en/delivery/stage-4/4-1.md"};function n(s,e,l,d,c,u){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="_4-1-set-triggers-and-proactive-suggestions" tabindex="-1">4.1 Set triggers and proactive suggestions <a class="header-anchor" href="#_4-1-set-triggers-and-proactive-suggestions" aria-label="Permalink to &quot;4.1 Set triggers and proactive suggestions&quot;">​</a></h1><h2 id="current-status" tabindex="-1">Current status <a class="header-anchor" href="#current-status" aria-label="Permalink to &quot;Current status&quot;">​</a></h2><ul><li><strong>Implemented:</strong> Six trigger types: deadline window, task failure or recoverability, uncertain external effect, approval wait timeout, new source entries, and queue backlog or long-running tasks; suggestions include provenance, reason, action, impact, cost, risk, and priority, and are deduplicated per event.</li><li><strong>Still open:</strong> Email and calendar triggers are disabled placeholders; proactive mode only creates suggestions and never executes high-risk actions directly.</li></ul><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Let Hearth find work worth handling in sources the user has authorized and explain why it needs attention now. This step only suggests; it does not automatically perform high-risk actions.</p><h2 id="how-to-do-it" tabindex="-1">How to do it <a class="header-anchor" href="#how-to-do-it" aria-label="Permalink to &quot;How to do it&quot;">​</a></h2><ol><li>Generate candidate events from email, calendar, files, and existing follow-ups.</li><li>Remove duplicates and add a cooldown so the same item is not raised repeatedly.</li><li>Each suggestion explains its source, why it matters now, the proposed action, expected impact, and whether approval is needed.</li><li>The user can accept, ignore, remind later, or turn it into a normal task.</li><li>Trial it without real impact first and observe whether suggestions are accurate and not excessive.</li><li>Do not enable proactive execution without clear authority, budget, and a stop control.</li></ol>',7)])])}const p=t(o,[["render",n]]);export{h as __pageData,p as default};
